// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 preFund, uint256 sendAmt, bytes calldata data) public {
        vm.assume(sendAmt <= type(uint128).max);
        vm.assume(preFund <= type(uint128).max);

        address owner = c.Owner();
        vm.deal(owner, preFund + sendAmt + 1);
        vm.prank(owner);
        (bool ok,) = payable(address(c)).call{value: preFund}("");
        require(ok);

        vm.prank(owner);
        bool success;
        try c.Command{value: sendAmt}(address(this), data) {
            success = true;
        } catch {
            success = false;
        }

        uint256 before = preFund;
        uint256 afterBal = address(c).balance;
        assertTrue(afterBal == before + sendAmt);
    }
}
